package com.vibecode.task.domain;
import jakarta.persistence.*; import java.util.UUID;
@Entity @Table(name="task_acceptance_criteria") public class TaskAcceptanceCriterionRecord { @Id private UUID id; @Column(name="task_id",nullable=false) private UUID taskId; @Column(nullable=false,columnDefinition="TEXT") private String description; @Column(nullable=false) private boolean required; @Enumerated(EnumType.STRING) @Column(nullable=false) private CriterionStatus status; protected TaskAcceptanceCriterionRecord(){} public TaskAcceptanceCriterionRecord(UUID taskId,String description,boolean required){id=UUID.randomUUID();this.taskId=taskId;this.description=description;this.required=required;status=CriterionStatus.PENDING;} public UUID id(){return id;} public String description(){return description;} public boolean required(){return required;} public CriterionStatus status(){return status;} public void status(CriterionStatus s){status=s;} }
